import json,itertools
w=json.loads(context)
qs={s:[] for s in w['skus']}
for q in w['quotes']:
 d=w['skus'][q['sku']]
 if q['quality']=='approved' and d['demand']<=q['units']<=d['demand']+2 and q['arrival']<=d['deadline']:
  qs[q['sku']].append(q)
vd={v['id']:v for v in w['vendors']}
best=None; bestsel=None
for sel in itertools.product(*(qs[s] for s in w['skus'])):
 bysku={q['sku']:q for q in sel}
 if any(q['needs_same_vendor_sku'] and bysku[q['needs_same_vendor_sku']]['vendor']!=q['vendor'] for q in sel): continue
 vendors={q['vendor'] for q in sel}
 if len(vendors)<3 or sum(q['carbon'] for q in sel)>w['carbon_cap']: continue
 units={v:sum(q['units'] for q in sel if q['vendor']==v) for v in vd}
 if any(units[v]>vd[v]['unit_cap'] for v in vd): continue
 cost=0
 for v in vendors:
  qq=[q for q in sel if q['vendor']==v]
  gross=sum(q['units']*q['unit_cents'] for q in qq)
  merch=(gross*(10000-vd[v]['tier_bps'])+5000)//10000 if units[v]>=vd[v]['tier_units'] else gross
  cost+=merch
  if gross<vd[v]['free_shipping_gross']: cost+=vd[v]['shipping_cents']
  if len({q['sku'] for q in qq})>=2 and merch>=vd[v]['rebate_merchandise_min']: cost-=vd[v]['rebate_cents']
 if best is None or cost<best: best=cost; bestsel=sel
print(best,[(q['id'],q['vendor']) for q in bestsel])
